package updater.qa;
import android.app.*;
import android.content.*;
import android.os.*;
import java.io.*;
import java.lang.reflect.*;
import java.net.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;

/** Real signed APK validation and deterministic network faults; no server or account changes. */
public class UpdateChecks extends TestBase {
    Class<?> type,releaseType,factoryType,clockType;Bundle options;File candidate;String digest;long now=System.currentTimeMillis();final List<Object> models=new ArrayList<>();
    static final class TestContext extends ContextWrapper {
        final String prefix="qa-update-"+UUID.randomUUID()+"-";final File cache;final List<SharedPreferences> preferences=new ArrayList<>();
        TestContext(Context base){super(base);cache=new File(base.getCacheDir(),prefix);cache.mkdirs();}
        public Context getApplicationContext(){return this;}
        public File getCacheDir(){return cache;}
        public SharedPreferences getSharedPreferences(String name,int mode){SharedPreferences p=super.getSharedPreferences(prefix+name,mode);preferences.add(p);return p;}
    }
    static class Fake implements InvocationHandler {
        final File file;final JSONObject release;int checks,requests;boolean fail,cut,ignoreRange,badRange,corrupt;int delay;String lastRange;
        Fake(File file,JSONObject release){this.file=file;this.release=release;}
        public Object invoke(Object proxy,Method method,Object[] args)throws Throwable{if(method.getName().equals("open")){URL url=(URL)args[0];boolean api=url.getPath().endsWith("/latest");if(api)checks++;else requests++;return new Connection(url,this,api,requests);}if(method.getName().equals("toString"))return "Private update fixture";return null;}
    }
    static final class Connection extends HttpURLConnection {
        final Fake source;final boolean api;final int request;InputStream input;
        Connection(URL url,Fake source,boolean api,int request){super(url);this.source=source;this.api=api;this.request=request;}
        public void connect(){}public boolean usingProxy(){return false;}
        long start(){String range=getRequestProperty("Range");source.lastRange=range;return range==null||source.ignoreRange?0:Long.parseLong(range.substring(6,range.length()-1));}
        public int getResponseCode(){return api?(source.fail?503:200):getRequestProperty("Range")!=null&&!source.ignoreRange?206:200;}
        public String getHeaderField(String key){if("Content-Range".equalsIgnoreCase(key)){long start=start()+(source.badRange?1:0);return "bytes "+start+"-"+(source.file.length()-1)+"/"+source.file.length();}return null;}
        public InputStream getInputStream()throws IOException{if(api)return new ByteArrayInputStream(source.release.toString().getBytes("UTF-8"));long offset=start();FileInputStream file=new FileInputStream(source.file);file.getChannel().position(offset);input=new FilterInputStream(file){long count;public int read(byte[] b,int off,int len)throws IOException{if(source.cut&&request==1&&count>=1048576)throw new IOException("Injected interruption");if(source.cut&&request==1)len=(int)Math.min(len,1048576-count);int n=super.read(b,off,len);if(n>0){if(source.corrupt&&count==0)b[off]^=1;count+=n;if(source.delay>0)try{Thread.sleep(source.delay);}catch(InterruptedException e){throw new IOException(e);}}return n;}};return input;}
        public void disconnect(){if(input!=null)try{input.close();}catch(IOException ignored){}}
    }
    String sha(File file)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] b=new byte[65536];for(int n;(n=in.read(b))!=-1;)d.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte b:d.digest())s.append(String.format(Locale.US,"%02x",b&255));return s.toString();}
    JSONObject metadata(File file,String v)throws Exception{String hash=sha(file);JSONArray assets=new JSONArray().put(new JSONObject().put("name","guide.zip"));for(boolean tv:new boolean[]{true}){String name="QianqiuLive-"+v+".apk";assets.put(new JSONObject().put("name",name).put("state","uploaded").put("size",file.length()).put("digest","sha256:"+hash).put("browser_download_url","https://github.com/suqianqiu/qianqiu-live/releases/download/v"+v+"/"+name));}return new JSONObject().put("tag_name","v"+v).put("draft",false).put("prerelease",false).put("body","# 产品更新\n- 每日检查更新\n- 引导开启安装授权").put("assets",assets);}
    Object model(Context c,Fake fake)throws Exception{Object network=java.lang.reflect.Proxy.newProxyInstance(factoryType.getClassLoader(),new Class[]{factoryType},fake),clock=java.lang.reflect.Proxy.newProxyInstance(clockType.getClassLoader(),new Class[]{clockType},(p,m,a)->m.getName().equals("now")?now:null);Object model=make(type,new Class[]{Context.class,factoryType,clockType},c,network,clock);models.add(model);return model;}
    void invoke(Object model,String name,Class<?>[] params,Object...args)throws Exception{call(type,model,name,params,args);}
    Object state(Object model)throws Exception{return call(type,model,"state",new Class[]{});}
    String phase(Object model)throws Exception{return field(state(model),"phase").toString();}
    void waitIdle(Object model)throws Exception{long end=SystemClock.elapsedRealtime()+90000;while(SystemClock.elapsedRealtime()<end){state(model);if(!(Boolean)field(model,"working"))return;SystemClock.sleep(30);}throw new AssertionError("Update operation timed out");}
    void check(Object model,boolean manual)throws Exception{invoke(model,"check",new Class[]{boolean.class},manual);waitIdle(model);}
    void download(Object model)throws Exception{invoke(model,"download",new Class[]{});waitIdle(model);}
    void copy(File source,File target,long limit)throws Exception{target.getParentFile().mkdirs();try(InputStream in=new FileInputStream(source);OutputStream out=new FileOutputStream(target)){byte[] b=new byte[65536];for(int n;limit>0&&(n=in.read(b,0,(int)Math.min(limit,b.length)))!=-1;){out.write(b,0,n);limit-=n;}}}
    void rejects(Callable<?> work,String message)throws Exception{boolean bad=false;try{work.call();}catch(Exception expected){bad=true;}require(bad,message);}
    @Override public void onCreate(Bundle args){options=args==null?new Bundle():args;super.onCreate(args);}
    void load()throws Exception{context=getTargetContext();type=Class.forName("com.tv.simplelive.AppUpdate");releaseType=Class.forName(type.getName()+"$Release");factoryType=Class.forName(type.getName()+"$ConnectionFactory");clockType=Class.forName(type.getName()+"$Clock");candidate=new File(context.getFilesDir(),"update-new.apk");require(candidate.length()>1000000,"signed update fixture exists");digest=sha(candidate);}
    @Override public void onStart(){context=getTargetContext();Bundle result=new Bundle();List<TestContext> isolated=new ArrayList<>();
        try{TimeZone.setDefault(TimeZone.getTimeZone("Asia/Shanghai"));load();require((Boolean)call(type,null,"newer",new Class[]{String.class,String.class},"0.1.100","0.1.99"),"version comparison is numeric");require(!(Boolean)call(type,null,"newer",new Class[]{String.class,String.class},"0.1.9","1.3.4"),"older releases cannot downgrade");require((Boolean)call(type,null,"preferTv",new Class[]{String[].class},(Object)new String[]{"arm64-v8a","armeabi-v7a"}),"ARM selects TV package");require(!(Boolean)call(type,null,"preferTv",new Class[]{String[].class},(Object)new String[]{"x86_64","arm64-v8a"}),"native x86 preference beats translated ARM");
            JSONObject data=metadata(candidate,"1.3.5");Object selected=call(type,null,"parse",new Class[]{JSONObject.class,boolean.class},data,true);require(field(selected,"name").equals("QianqiuLive-1.3.5.apk"),"correct APK selected among unrelated assets");JSONObject invalid=new JSONObject(data.toString()).put("prerelease",true);rejects(()->call(type,null,"parse",new Class[]{JSONObject.class,boolean.class},invalid,true),"preview releases rejected");JSONObject unsafe=new JSONObject(data.toString());unsafe.getJSONArray("assets").getJSONObject(1).put("browser_download_url","https://evil.invalid/update.apk");rejects(()->call(type,null,"parse",new Class[]{JSONObject.class,boolean.class},unsafe,true),"foreign download source rejected");JSONObject missing=new JSONObject(data.toString());missing.getJSONArray("assets").getJSONObject(1).remove("digest");rejects(()->call(type,null,"parse",new Class[]{JSONObject.class,boolean.class},missing,true),"missing digest rejected");
            TestContext tc=new TestContext(context);isolated.add(tc);Fake network=new Fake(candidate,data);Object daily=model(tc,network);long dayStart=((now+8*3600000L)/86400000L)*86400000L-8*3600000L;now=dayStart+23*3600000L+50*60000L;check(daily,false);require(network.checks==1&&phase(daily).equals("AVAILABLE"),"first open checks asynchronously");check(daily,false);require(network.checks==1,"same Beijing day checks once");now+=20*60000;check(daily,false);require(network.checks==2,"new Beijing day checks despite recent successful request");check(daily,true);require(network.checks==3,"manual check can refresh within the day");
            tc=new TestContext(context);isolated.add(tc);network=new Fake(candidate,data);network.fail=true;Object failure=model(tc,network);check(failure,false);require(phase(failure).equals("ERROR"),"network failure is reported without activity crash");now+=10*60000;check(failure,false);require(network.checks==1,"failed automatic requests have backoff");network.fail=false;now+=21*60000;check(failure,false);require(network.checks==1&&phase(failure).equals("ERROR"),"failed first launch does not retry automatically that day");check(failure,true);require(network.checks==2&&phase(failure).equals("AVAILABLE"),"manual check can recover within same day");
            tc=new TestContext(context);isolated.add(tc);network=new Fake(candidate,data);network.cut=true;Object resumed=model(tc,network);check(resumed,true);download(resumed);require(phase(resumed).equals("PAUSED")&&((File)field(resumed,"part")).length()==1048576,"interrupted download preserves bytes");download(resumed);require(phase(resumed).equals("READY")&&"bytes=1048576-".equals(network.lastRange),"resume requests exact remaining byte range");require(sha((File)field(resumed,"apk")).equals(digest),"resumed APK matches complete digest");
            tc=new TestContext(context);isolated.add(tc);network=new Fake(candidate,data);network.ignoreRange=true;Object ignored=model(tc,network);check(ignored,true);copy(candidate,(File)field(ignored,"part"),131072);download(ignored);require(phase(ignored).equals("READY")&&((File)field(ignored,"apk")).length()==candidate.length(),"server ignoring Range safely restarts rather than appends");
            tc=new TestContext(context);isolated.add(tc);network=new Fake(candidate,data);network.badRange=true;Object mismatch=model(tc,network);check(mismatch,true);copy(candidate,(File)field(mismatch,"part"),131072);download(mismatch);require(phase(mismatch).equals("PAUSED")&&((File)field(mismatch,"part")).length()==131072,"wrong Content-Range cannot corrupt existing progress");
            tc=new TestContext(context);isolated.add(tc);network=new Fake(candidate,data);Object full=model(tc,network);check(full,true);copy(candidate,(File)field(full,"part"),candidate.length());download(full);require(phase(full).equals("READY")&&network.requests==0,"completed partial file validates without requesting an invalid range");
            tc=new TestContext(context);isolated.add(tc);network=new Fake(candidate,data);network.corrupt=true;Object corrupt=model(tc,network);check(corrupt,true);download(corrupt);require(phase(corrupt).equals("AVAILABLE")&&!((File)field(corrupt,"part")).exists()&&!((File)field(corrupt,"apk")).exists(),"corrupt payload is removed and cannot install");
            final Object validator=resumed;File wrong=new File(context.getFilesDir(),"update-wrong-signature.apk");require(wrong.exists(),"wrong-signature fixture exists");Object wrongRelease=call(type,null,"parse",new Class[]{JSONObject.class,boolean.class},metadata(wrong,"1.3.5"),false);rejects(()->call(type,validator,"validateApk",new Class[]{File.class,releaseType},wrong,wrongRelease),"matching hash cannot bypass signing identity");File old=new File(context.getApplicationInfo().sourceDir);Object oldRelease=call(type,null,"parse",new Class[]{JSONObject.class,boolean.class},metadata(old,"1.3.4"),false);rejects(()->call(type,validator,"validateApk",new Class[]{File.class,releaseType},old,oldRelease),"same version cannot be installed as an upgrade");

            require((Boolean)call(type,daily,"shouldPrompt",new Class[]{}),"new release can prompt");invoke(daily,"markPrompted",new Class[]{});require(!(Boolean)call(type,daily,"shouldPrompt",new Class[]{}),"prompt suppressed after dismissal that day");now+=86400000L;require((Boolean)call(type,daily,"shouldPrompt",new Class[]{}),"new calendar day can prompt again");
            TestContext persistent=new TestContext(context);isolated.add(persistent);Fake firstNetwork=new Fake(candidate,data);Object first=model(persistent,firstNetwork);check(first,false);Fake nextNetwork=new Fake(candidate,data);Object restarted=model(persistent,nextNetwork);check(restarted,false);require(nextNetwork.checks==0,"daily attempt survives process/model recreation");
            TimeZone.setDefault(TimeZone.getTimeZone("America/New_York"));long stamp=1794448800000L;require(call(type,null,"day",new Class[]{long.class},stamp).equals("2026-11-11"),"daily boundary follows device timezone");TimeZone.setDefault(TimeZone.getTimeZone("Asia/Shanghai"));
            result.putString("result","PASS");
        }catch(Throwable e){result.putString("result","FAIL");result.putString("error",e.toString());}
        finally{for(Object model:models)try{((ExecutorService)field(model,"work")).shutdownNow();}catch(Exception ignored){}for(TestContext c:isolated){for(SharedPreferences p:c.preferences)p.edit().clear().commit();remove(c.cache);}}
        result.putInt("checks",checks);try{JSONObject report=new JSONObject().put("result",result.getString("result")).put("checks",checks).put("cases",new JSONArray(cases));if(result.containsKey("error"))report.put("error",result.getString("error"));try(OutputStream out=new FileOutputStream(new File(context.getExternalFilesDir("qa"),"update-checks-results.json"))){out.write(report.toString(2).getBytes("UTF-8"));}}catch(Exception ignored){}finish("PASS".equals(result.getString("result"))?-1:0,result);
    }
}
